package adf_test

// Tests for adf.Parse (WP-T1). Spec: architecture §2.4, ux-spec §14.4, jira-sync §2.14, testing §4 (internal/adf).
//
// Layout: raw ADF inputs live in testdata/adf/<name>.json, hand-written expected normalised Docs in
// testdata/adf/<name>.golden.json. `go test ./internal/adf -update` rewrites goldens from the implementation: review
// the diff against the spec before committing. The goldens were written by hand, never generated by the code.
// mob1421_description.golden.json is the `description` of frontend/src/api/fixtures/ticket_mob1421.json verbatim.
//
// SPEC-NOTE (date nodes, discriminating case in TestParse_DateNodes_UseTheCalendarDateOfTheTimestamp): contract.go says
// Attrs.Date is "local YYYY-MM-DD". ADF date timestamps are epoch-ms strings at UTC midnight of the date the author
// picked, so converting them to a negative-offset local zone would show the previous day (Atlassian renders them in
// UTC). These tests read "the calendar date the author picked" = the timestamp's UTC date. Past = that date is before
// Now()'s local calendar day (same day is not past). The general goldens use Now in UTC so they read either way.
// SPEC-NOTE (Collapsed): raw ADF has no persisted collapsed state; the tests read the boolean `attrs.collapsed` as
// authored, absent = false (expand open).
// SPEC-NOTE (decisionList): each decisionItem's inline content is wrapped in one `p`; taskItem children stay inline
// (no `p`), as in the reference fixture.
// SPEC-NOTE (attr pass-through): ol order, colspan, rowspan, colwidth are passed through as authored; absent = zero
// value (no key). No `"a"` key at all when every attr is zero.
// SPEC-NOTE (tr.header): a tableRow whose cells are all tableHeader gets Attrs.Header; a tableHeader inside a normal
// row is a `th` (header column) and the row has no header flag.
// SPEC-NOTE (status): label is kept as authored; colours neutral/blue/purple/yellow/green/red map to
// todo/prog/review/qa/done/alert; an unknown or missing colour maps to todo.
// SPEC-NOTE (panel): an unknown panelType (e.g. "custom") becomes the info panel.
// SPEC-NOTE (mention label): Resolver.Person name when non-empty, else attrs.text without the leading "@".
// SPEC-NOTE (emoji): Emoji = attrs.text glyph; when attrs.text is absent or equals the shortName (custom emoji), Emoji
// is "" and ShortName is set.
// SPEC-NOTE (cards): a resolved card carries the issue fields plus URL (no Host/Path); an unresolved one carries only
// URL/Host/Path. blockCard / external mediaSingle set Block. External media (attrs.type=="external") becomes a Block
// link `card`, and the Resolver is not consulted for it.
// SPEC-NOTE (media): media and file nodes copy Name/Mime/Bytes/Cached from the resolved attachment (Cached also on
// files, as in the fixture). Width/Height = media node attrs as authored, else the attachment's stored size; Layout =
// the mediaSingle layout as authored; Caption = the text of the mediaSingle's caption child. Unresolved media keeps
// authored Width/Height/Layout and sets Missing (no AttachmentID/Name/Cached).
// SPEC-NOTE (mediaGroup/mediaInline): a mediaGroup is flattened into one `file` node per media child, in place.
// mediaInline resolving to an image attachment becomes `media` (Block=false); to anything else a `file`. Images inside a
// mediaGroup are unspecified and not tested.
// SPEC-NOTE (unknown): text of an unknown node = the concatenation of all descendant text nodes with no separator; an
// unknown subtree counts once in Doc.Unsupported; known ancestors/siblings are still rendered.
// SPEC-NOTE (malformed input): non-JSON raw becomes one unknown node whose Text is the raw string verbatim, Unsupported=1.
// SPEC-NOTE (marks): marks keep authored order; unknown marks (backgroundColor, annotation, alignment…) are dropped; a
// textColor that is not exactly #rrggbb is dropped; a link whose href is not http, https or mailto is dropped
// (defence in depth: TS renders an anchor).

import (
	"encoding/json"
	"flag"
	"os"
	"path/filepath"
	"sort"
	"strconv"
	"strings"
	"testing"
	"time"

	"github.com/crueber/cuisle/internal/adf"
	"github.com/crueber/cuisle/internal/model"
)

var update = flag.Bool("update", false, "rewrite testdata/adf/*.golden.json from the implementation (review the diff!)")

// ---- fake resolver ----

// resolverNow is between 18 Nov and 1 Dec 2026, in UTC.
var resolverNow = time.Date(2026, 11, 23, 12, 0, 0, 0, time.UTC)

type fakeAtt struct {
	att    model.Attachment
	cached string
}

type fakeResolver struct {
	now    time.Time
	calls  []string
	atts   map[string]fakeAtt
	issues map[string]adf.ResolvedIssue
}

func newResolver() *fakeResolver {
	return &fakeResolver{
		now: resolverNow,
		atts: map[string]fakeAtt{
			"m-201": {model.Attachment{LocalID: 201, ID: "10201", Name: "unit-toggle-v3.png", Mime: "image/png", Bytes: 182540, MediaFileID: "m-201", Width: 1200, Height: 720}, adf.CachedFull},
			"m-202": {model.Attachment{LocalID: 202, ID: "10202", Name: "conversion-flow.png", Mime: "image/png", Bytes: 47477, MediaFileID: "m-202", Width: 1200, Height: 440}, adf.CachedThumb},
			"m-203": {model.Attachment{LocalID: 203, ID: "10203", Name: "unit-spec.pdf", Mime: "application/pdf", Bytes: 412000, MediaFileID: "m-203"}, adf.CachedNone},
			"m-204": {model.Attachment{LocalID: 204, ID: "10204", Name: "icon.png", Mime: "image/png", Bytes: 4096, MediaFileID: "m-204", Width: 32, Height: 32}, adf.CachedFull},
		},
		issues: map[string]adf.ResolvedIssue{
			"https://example.atlassian.net/browse/MOB-1200": {IssueID: 900, Key: "MOB-1200", Summary: "Recipe units v2", TypeKind: "epic", StatusName: "In Progress", StatusLozenge: "prog"},
			"https://example.atlassian.net/browse/MOB-1429": {IssueID: 901, Key: "MOB-1429", Summary: "Edit states", TypeKind: "story", StatusName: "In Review", StatusLozenge: "review"},
		},
	}
}

func (r *fakeResolver) Attachment(mediaFileID, alt string) (model.Attachment, string, bool) {
	r.calls = append(r.calls, "att:"+mediaFileID+"|"+alt)
	a, ok := r.atts[mediaFileID]
	return a.att, a.cached, ok
}

func (r *fakeResolver) Issue(url string) (adf.ResolvedIssue, bool) {
	r.calls = append(r.calls, "issue:"+url)
	i, ok := r.issues[url]
	return i, ok
}

func (r *fakeResolver) Person(accountID string) (string, bool) {
	r.calls = append(r.calls, "person:"+accountID)
	switch accountID {
	case "silas":
		return "Silas Marchetti", false
	case "me":
		return "Dev User", true
	}
	return "", false
}

func (r *fakeResolver) Now() time.Time { return r.now }

// ---- helpers ----

func rich(raw string) model.RichText {
	return model.RichText{Format: model.RichTextADF, Raw: json.RawMessage(raw)}
}

// canon turns any JSON-marshalable value (or raw JSON bytes) into a canonical indented string (sorted keys), so a nil
// slice and an absent key compare by what they serialise to, and diffs are readable.
func canon(t *testing.T, v any) string {
	t.Helper()
	var b []byte
	switch x := v.(type) {
	case []byte:
		b = x
	case json.RawMessage:
		b = x
	default:
		var err error
		b, err = json.Marshal(v)
		if err != nil {
			t.Fatalf("marshal: %v", err)
		}
	}
	var any1 any
	if err := json.Unmarshal(b, &any1); err != nil {
		t.Fatalf("unmarshal %q: %v", b, err)
	}
	out, err := json.MarshalIndent(any1, "", "  ")
	if err != nil {
		t.Fatalf("marshal canon: %v", err)
	}
	return string(out)
}

func fixtureNames(t *testing.T) []string {
	t.Helper()
	files, err := filepath.Glob(filepath.Join("testdata", "adf", "*.json"))
	if err != nil {
		t.Fatal(err)
	}
	var names []string
	for _, f := range files {
		if strings.HasSuffix(f, ".golden.json") {
			continue
		}
		names = append(names, strings.TrimSuffix(filepath.Base(f), ".json"))
	}
	sort.Strings(names)
	if len(names) < 40 {
		t.Fatalf("expected at least 40 ADF fixtures in testdata/adf, found %d", len(names))
	}
	return names
}

func parseFixture(t *testing.T, name string) adf.Doc {
	t.Helper()
	raw, err := os.ReadFile(filepath.Join("testdata", "adf", name+".json"))
	if err != nil {
		t.Fatal(err)
	}
	return adf.Parse(rich(string(raw)), newResolver())
}

// ---- golden: one fixture per node and mark of ux-spec §14.4 ----

func TestParse_Goldens(t *testing.T) {
	for _, name := range fixtureNames(t) {
		t.Run(name, func(t *testing.T) {
			doc := parseFixture(t, name)
			golden := filepath.Join("testdata", "adf", name+".golden.json")
			if *update {
				out, err := json.MarshalIndent(doc, "", "  ")
				if err != nil {
					t.Fatal(err)
				}
				if err := os.WriteFile(golden, append(out, '\n'), 0o644); err != nil {
					t.Fatal(err)
				}
				return
			}
			want, err := os.ReadFile(golden)
			if err != nil {
				t.Fatalf("golden missing for %s: %v", name, err)
			}
			if g, w := canon(t, doc), canon(t, want); g != w {
				t.Errorf("Parse(%s) differs from %s\n--- got ---\n%s\n--- want ---\n%s", name, golden, g, w)
			}
		})
	}
}

// Every normalised node type and every mark must show up in what Parse produces for the fixtures (the contract's
// NodeTypes / Mark* lists), so no node can lose its golden.
func TestParse_FixturesCoverEveryNodeTypeAndMark(t *testing.T) {
	nodes := map[string]bool{}
	marks := map[string]bool{}
	var walk func(ns []adf.Node)
	walk = func(ns []adf.Node) {
		for _, n := range ns {
			nodes[n.T] = true
			for _, m := range n.Marks {
				marks[m.T] = true
			}
			walk(n.C)
		}
	}
	for _, name := range fixtureNames(t) {
		walk(parseFixture(t, name).Nodes)
	}
	for _, ty := range adf.NodeTypes {
		if !nodes[ty] {
			t.Errorf("no fixture produces a %q node", ty)
		}
	}
	for _, m := range []string{adf.MarkStrong, adf.MarkEm, adf.MarkStrike, adf.MarkUnderline, adf.MarkSub, adf.MarkSup, adf.MarkCode, adf.MarkLink, adf.MarkColor} {
		if !marks[m] {
			t.Errorf("no fixture produces a %q mark", m)
		}
	}
	for _, p := range []string{adf.PanelInfo, adf.PanelNote, adf.PanelSuccess, adf.PanelWarning, adf.PanelError} {
		found := false
		for _, name := range fixtureNames(t) {
			var scan func(ns []adf.Node)
			scan = func(ns []adf.Node) {
				for _, n := range ns {
					if n.T == adf.NodePanel && n.A != nil && n.A.Panel == p {
						found = true
					}
					scan(n.C)
				}
			}
			scan(parseFixture(t, name).Nodes)
		}
		if !found {
			t.Errorf("no fixture produces a %q panel", p)
		}
	}
}

// ---- empty, unknown and malformed input ----

func TestParse_EmptyUnknownAndMalformedInput(t *testing.T) {
	const unknownDoc = `{"version":1,"type":"doc","content":[{"type":"mystery","content":[{"type":"text","text":"abc"}]}]}`
	tests := []struct {
		name string
		raw  model.RichText
		want string // canonical JSON of the Doc
	}{
		{"nil raw is an empty doc", model.RichText{Format: model.RichTextADF}, `{"c":[]}`},
		{"JSON null is an empty doc", rich(`null`), `{"c":[]}`},
		{"doc with no content is an empty doc", rich(`{"version":1,"type":"doc","content":[]}`), `{"c":[]}`},
		{"unknown top-level node keeps its text and counts", rich(unknownDoc), `{"c":[{"t":"unknown","x":"abc"}],"u":1}`},
		{"malformed JSON becomes one unknown node with the raw text", rich(`{not json`), `{"c":[{"t":"unknown","x":"{not json"}],"u":1}`},
		{"truncated JSON becomes one unknown node with the raw text",
			rich(`{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"hel`),
			`{"c":[{"t":"unknown","x":"{\"type\":\"doc\",\"content\":[{\"type\":\"paragraph\",\"content\":[{\"type\":\"text\",\"text\":\"hel"}],"u":1}`},
		{"plain non-JSON text becomes one unknown node", rich(`plain words`), `{"c":[{"t":"unknown","x":"plain words"}],"u":1}`},
	}
	for _, tc := range tests {
		t.Run(tc.name, func(t *testing.T) {
			var doc adf.Doc
			func() {
				defer func() {
					if r := recover(); r != nil {
						t.Fatalf("Parse panicked: %v", r)
					}
				}()
				doc = adf.Parse(tc.raw, newResolver())
			}()
			if g, w := canon(t, doc), canon(t, []byte(tc.want)); g != w {
				t.Errorf("got\n%s\nwant\n%s", g, w)
			}
		})
	}
}

// ---- the resolver contract ----

func TestParse_AsksTheResolverWithTheDocumentsReferences(t *testing.T) {
	r := newResolver()
	adf.Parse(rich(`{"version":1,"type":"doc","content":[
	  {"type":"mediaSingle","attrs":{"layout":"center"},"content":[{"type":"media","attrs":{"id":"m-201","type":"file","collection":"c","alt":"unit-toggle-v3.png"}}]},
	  {"type":"paragraph","content":[
	    {"type":"inlineCard","attrs":{"url":"https://example.atlassian.net/browse/MOB-1200"}},
	    {"type":"mention","attrs":{"id":"silas","text":"@Silas"}}]}]}`), r)
	got := strings.Join(r.calls, "\n")
	for _, want := range []string{
		"att:m-201|unit-toggle-v3.png",
		"issue:https://example.atlassian.net/browse/MOB-1200",
		"person:silas",
	} {
		if !strings.Contains(got, want) {
			t.Errorf("resolver was not called with %q; calls:\n%s", want, got)
		}
	}
}

func TestParse_ExternalMediaIsNeverResolvedAsAnAttachment(t *testing.T) {
	r := newResolver()
	doc := adf.Parse(rich(`{"version":1,"type":"doc","content":[
	  {"type":"mediaSingle","attrs":{"layout":"center"},"content":[{"type":"media","attrs":{"type":"external","url":"https://img.example.com/pics/a.png"}}]}]}`), r)
	for _, c := range r.calls {
		if strings.HasPrefix(c, "att:") {
			t.Errorf("Resolver.Attachment was called for external media: %s", c)
		}
	}
	if len(doc.Nodes) != 1 || doc.Nodes[0].T != adf.NodeCard {
		t.Fatalf("external media should become one card node, got %s", canon(t, doc))
	}
}

// ---- date nodes (see the SPEC-NOTE at the top) ----

func TestParse_DateNodes_UseTheCalendarDateOfTheTimestamp(t *testing.T) {
	// Now: 2026-11-23 23:30 at UTC-6, which is already 2026-11-24 05:30 UTC.
	zone := time.FixedZone("UTC-6", -6*3600)
	r := newResolver()
	r.now = time.Date(2026, 11, 23, 23, 30, 0, 0, zone)

	tests := []struct {
		name   string
		ms     int64
		date   string
		isPast bool
	}{
		{"future date, UTC midnight", 1796083200000, "2026-12-01", false},
		{"today (local day), UTC midnight: not past", 1795392000000, "2026-11-23", false},
		{"yesterday, UTC midnight: past", 1795305600000, "2026-11-22", true},
		{"03:00Z on the 23rd keeps the 23rd (a local conversion would say the 22nd)", 1795402800000, "2026-11-23", false},
	}
	for _, tc := range tests {
		t.Run(tc.name, func(t *testing.T) {
			raw := `{"version":1,"type":"doc","content":[{"type":"paragraph","content":[{"type":"date","attrs":{"timestamp":"` + strconv.FormatInt(tc.ms, 10) + `"}}]}]}`
			doc := adf.Parse(rich(raw), r)
			if len(doc.Nodes) != 1 || len(doc.Nodes[0].C) != 1 || doc.Nodes[0].C[0].T != adf.NodeDate || doc.Nodes[0].C[0].A == nil {
				t.Fatalf("want one paragraph holding one date node, got %s", canon(t, doc))
			}
			a := doc.Nodes[0].C[0].A
			if a.Date != tc.date || a.Past != tc.isPast {
				t.Errorf("date=%q past=%v, want date=%q past=%v", a.Date, a.Past, tc.date, tc.isPast)
			}
		})
	}
}

// ---- fuzz: never panics, never fails ----

func FuzzParse(f *testing.F) {
	for _, s := range []string{
		``, `null`, `{}`, `[]`, `"x"`, `{not json`, `{"type":"doc"}`,
		`{"version":1,"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"hi","marks":[{"type":"link","attrs":{"href":"https://a.example"}}]}]}]}`,
		`{"version":1,"type":"doc","content":[{"type":"table","content":[{"type":"tableRow","content":[{"type":"tableCell"}]}]}]}`,
		`{"version":1,"type":"doc","content":[{"type":"mediaGroup","content":[{"type":"media"}]},{"type":"mediaSingle"},{"type":"date"}]}`,
	} {
		f.Add(s)
	}
	f.Fuzz(func(t *testing.T, s string) {
		raw := model.RichText{Format: model.RichTextADF, Raw: json.RawMessage(s)}
		doc := adf.Parse(raw, newResolver())
		if doc.Nodes == nil {
			t.Fatalf("Doc.Nodes must never be nil")
		}
		if _, err := json.Marshal(doc); err != nil {
			t.Fatalf("Doc does not marshal: %v", err)
		}
		_ = adf.PlainText(raw)
		if trimmed := strings.TrimSpace(s); trimmed != "" && !json.Valid([]byte(s)) {
			if len(doc.Nodes) != 1 || doc.Nodes[0].T != adf.NodeUnknown || doc.Unsupported != 1 {
				t.Fatalf("malformed input %q must become exactly one unknown node, got %s", s, canon(t, doc))
			}
		}
	})
}
